css.css:
body {
	display: flex;
	align-items: center;
}
.branda-login {
	margin-left: auto;
	margin-right: auto;
	background: transparent url(https://revalplastiques.com/app/plugins/ultimate-branding/inc/modules/login-screen/themes/tree/background.svg) no-repeat 0 50%;
	width: 1000px;
}
.branda-login #login {
	margin: 0 0 0 auto;
	padding: 20px 0;
}
#login form, #login h1 {
	width: 320px;
}
 #login h1 {
	 margin-left: 0;
}
@media screen and ( max-width: 1001px ) {
	.branda-login #login {
		margin: 20px 20px 20px auto;
		padding: 20px;
	}
	.branda-login {
		background-position-x: 20px;
	}
}
@media screen and ( max-width: 800px ) {
	.branda-login {
		width: 100%;
		margin: 20px auto;
		padding: 20px;
		background-color: rgba( 255, 255, 255, .7 );
	}
}
